const cleanArg=(v)=>{const t=String(v==null?'':v).trim();return /^\{[a-zA-Z0-9_]+\}$/.test(t)?'':t;};
const sleep=(ms)=>new Promise(r=>setTimeout(r,ms));
const norm=(v)=>(v||'').replace(/\xa0/g,' ').replace(/\s+/g,' ').trim();
const isVisible=(n)=>{if(!n||!(n instanceof Element))return false;const s=getComputedStyle(n);if(s.visibility==='hidden'||s.display==='none')return false;const r=n.getBoundingClientRect();return r.width>0&&r.height>0;};
const txt=(n)=>norm(n&&n.textContent||'');
const realClick=(n)=>{if(!n)return;n.scrollIntoView({block:'center'});const r=n.getBoundingClientRect();const cx=(r.left||0)+(r.width||0)/2;const cy=(r.top||0)+(r.height||0)/2;['pointerover','pointerenter','pointermove','pointerdown','mousedown','pointerup','mouseup','click'].forEach(e=>{const Ev=e.startsWith('pointer')?PointerEvent:MouseEvent;n.dispatchEvent(new Ev(e,{bubbles:true,cancelable:true,button:0,pointerType:'mouse',isPrimary:true,clientX:cx,clientY:cy}));});};
const arrowKey=(el,k,kc)=>{el.dispatchEvent(new KeyboardEvent('keydown',{key:k,code:k,keyCode:kc,which:kc,bubbles:true,cancelable:true}));el.dispatchEvent(new KeyboardEvent('keyup',{key:k,code:k,keyCode:kc,which:kc,bubbles:true,cancelable:true}));};
const closeMenus=async()=>{for(let i=0;i<4;i++){if(!document.querySelector('[role=menu][data-state=open]'))return;document.body.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',keyCode:27,bubbles:true}));await sleep(150);}};
const waitFor=async(fn,ms)=>{const d=Date.now()+(ms||5000);for(;;){let v=null;try{v=fn();}catch(e){}if(v)return v;if(Date.now()>d)return null;await sleep(120);}};
const scopes=()=>Array.from(document.querySelectorAll('[role=menu],[role=dialog],[role=listbox],[data-radix-popper-content-wrapper],[data-radix-menu-content],[data-testid=composer-intelligence-picker-content]')).filter(isVisible);
const cands=()=>{const out=[];for(const sc of scopes())for(const n of sc.querySelectorAll('[role=menuitem],[role=menuitemradio],[role=menuitemcheckbox],[role=option],[role=slider],button,[role=button],a,li,div[tabindex]'))if(isVisible(n)&&(txt(n)||n.getAttribute('aria-label'))&&!n.closest('[inert],[aria-hidden=true]')&&out.indexOf(n)<0)out.push(n);return out;};
const leaves=(list)=>list.filter(n=>!list.some(o=>o!==n&&n.contains(o)));
const dump=()=>JSON.stringify(leaves(cands()).slice(0,25).map(n=>({tag:String(n.tagName||'').toLowerCase(),role:n.getAttribute('role'),testid:n.getAttribute('data-testid'),aria:n.getAttribute('aria-label'),text:txt(n).slice(0,48)})));
/* The composer picker is one flat panel. Captured live 2026-08-31:
     button[aria-haspopup=menu]                            composer pill, text = current tier
     [data-testid=composer-intelligence-picker-content]     the panel
       div[role=menuitem][aria-label="Select model"]        toggles the model view; its text is the TIER, not a model
       [data-testid=...slider-simple-view]  "<Tier>, N of 5. Use Left and Right arrow keys to adjust power."
         div[role=menuitem][aria-label=Power]  tabindex=0   <- arrow keys go HERE
           span[role=slider] aria-valuenow/min/max          <- 0..4, no aria-valuetext
       [data-testid=...slider-advanced-view]
         div[role=menuitemradio] aria-checked  "GPT-5.6 Sol" / "GPT-5.5"                                        */
const panel=()=>Array.from(document.querySelectorAll('[data-testid=composer-intelligence-picker-content]')).filter(isVisible)[0]||null;
const sliderEl=()=>{const p=panel();return p?p.querySelector('[role=slider]'):null;};
const powerRow=()=>{const p=panel();return p?p.querySelector('[aria-label=Power]'):null;};
const selectModelRow=()=>{const p=panel();return p?p.querySelector('[aria-label="Select model"]'):null;};
const modelRadios=()=>{const p=panel();return p?Array.from(p.querySelectorAll('[role=menuitemradio]')).filter(isVisible):[];};
/* The slider carries no aria-valuetext. The tier label exists only in the simple view's text. */
const tierNow=()=>{const p=panel();if(!p)return '';const v=p.querySelector('[data-testid=composer-model-picker-slider-simple-view]');const m=norm(v&&v.textContent||'').match(/^([^,]+),/);return m?norm(m[1]):'';};
const findPill=()=>{const inComposer=(b)=>!!(b.closest('form')||b.closest('[class*=composer]')||b.closest('[data-type=unified-composer]'));for(const s of ['button.__composer-pill[aria-haspopup=menu]','button[data-testid="model-switcher-dropdown-button"]','[data-testid*="model-switcher"][aria-haspopup=menu]']){const n=Array.from(document.querySelectorAll(s)).filter(isVisible)[0];if(n)return n;}return Array.from(document.querySelectorAll('button[aria-haspopup=menu],[role=button][aria-haspopup=menu]')).filter(isVisible).filter(b=>{const t=txt(b);return t.length>0&&t.length<40;}).find(inComposer)||null;};
const openPicker=async()=>{await closeMenus();const pill=findPill();if(!pill)throw new Error('model_picker_not_found: no composer pill button[aria-haspopup=menu]');realClick(pill);const p=await waitFor(panel,6000);if(!p){const d=dump();await closeMenus();throw new Error('picker_menu_not_found: the composer pill opened but no [data-testid=composer-intelligence-picker-content] panel appeared; visible='+d);}return p;};
const pickKey=(v)=>norm(v).toLowerCase().replace(/^(chat)?gpt[\s‑-]*/,'');
const pick=(opts,want)=>{const w=want.toLowerCase();const k=pickKey(want);return opts.find(n=>txt(n).toLowerCase()===w)||opts.find(n=>txt(n).toLowerCase().startsWith(w))||opts.find(n=>pickKey(txt(n))===k)||opts.find(n=>pickKey(txt(n)).startsWith(k))||null;};

const desiredModel=cleanArg(arg0)||'GPT-5.6 Sol';
const desiredEffort=cleanArg(arg1)||'Medium';
const requireExact=(cleanArg(arg2)||'true').toLowerCase()!=='false';
window.__rzn_chatgpt_picker={desiredModel,desiredEffort,requireExact};
await openPicker();
let radios=modelRadios();
if(!radios.length){const sel=selectModelRow();if(sel){realClick(sel);await waitFor(()=>modelRadios().length>0,3000);radios=modelRadios();}}
if(!radios.length){const d=dump();await closeMenus();throw new Error('model_options_not_found: the picker panel exposed no [role=menuitemradio] model rows, even after clicking Select model; visible='+d);}
const available=radios.map(txt);
const target=pick(radios,desiredModel);
if(!target){await closeMenus();throw new Error('model_not_found: wanted '+desiredModel+'; available='+JSON.stringify(available));}
const targetText=txt(target);
const checkedNow=()=>{const r=modelRadios().find(n=>txt(n)===targetText);return r?r.getAttribute('aria-checked')==='true':null;};
const alreadyChecked=target.getAttribute('aria-checked')==='true';
/* A plain click commits the radio and the panel stays open. Do NOT hand this row to a
   trusted CDP click: on the live popper that click does not register, and the run then
   sends on whatever model was already selected. */
if(!alreadyChecked){realClick(target);await waitFor(()=>checkedNow()===true,4000);}
if(checkedNow()!==true){const d2=dump();await closeMenus();throw new Error('model_commit_failed: clicked '+targetText+' but its radio never reported aria-checked=true; visible='+d2);}
return{ok:true,desiredModel,desiredEffort,requireExact,picker_mode:'slider',already_checked:alreadyChecked,model_committed:true,target_text:targetText,available_models:available};

