const valMax=()=>{const el=sliderEl();return el?Number(el.getAttribute('aria-valuemax')):NaN;};
const startIndex=valNow();
if(!Number.isInteger(startIndex)||!Number.isInteger(valMax()))throw new Error('effort_control_not_found: the Power slider exposed no integer aria-valuenow/aria-valuemax; valuenow='+valNow()+' valuemax='+valMax());
power.focus();
/* Harvest the ladder from the page instead of hardcoding it: walk to the minimum,
   then step up to the maximum reading the tier label the page prints at each stop.
   An account with a different set of tiers reports its own list in every error. */
for(let i=0;i<12&&valNow()>0;i++){arrowKey(power,'ArrowLeft',37);await sleep(180);}
if(valNow()!==0){await closeMenus();throw new Error('effort_slider_unresponsive: ArrowLeft did not drive the Power slider to its minimum; aria-valuenow='+valNow());}
