const selectTool=async()=>{if(!tool||tool==='none')return{selected:null};const wanted=TOOL_LABELS[tool];if(!wanted)return{selected:null,note:'unknown_tool',input:tool};const plus=document.querySelector('#composer-plus-btn');if(!plus)return{selected:null,note:'no_plus_btn'};realClick(plus);await sleep(600);const findRadio=()=>Array.from(document.querySelectorAll('[role=menuitemradio]')).filter(isVisible).find(el=>txt(el).toLowerCase()===wanted.toLowerCase());let target=findRadio();if(!target){const moreItem=Array.from(document.querySelectorAll('[role=menuitem]')).filter(isVisible).find(el=>/^\s*more\b/i.test(el.textContent||''));if(moreItem){realClick(moreItem);await sleep(500);target=findRadio();}}if(!target){await closeMenus();return{selected:null,note:'tool_not_in_menu',wanted};}realClick(target);await sleep(500);return{selected:wanted};};
